@sqlSet(SELECT z.approver FROM (SELECT *, (@i:=@i + 1) AS rows FROM (SELECT * FROM(SELECT a.EXT1 as approver, a.EXT2, '1' AS rank FROM orgdepartment a WHERE a.DEPARTMENTNO IN ('@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),4)','@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),3)', '@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),2)','@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM)') UNION ALL SELECT a.EXT4 as approver, a.EXT2, '2' AS rank FROM orgdepartment a WHERE a.DEPARTMENTNO IN ('@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),4)','@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),3)', '@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),2)','@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM)'))f ORDER BY f.EXT2 DESC,f.rank DESC)Q,(SELECT @i:=0) X) z WHERE z.rows >= (SELECT coalesce( max(rows),0) as rows FROM (SELECT *, (@f:=@f + 1) AS rows FROM (SELECT * FROM (SELECT a.EXT1 as approver, a.EXT2, '1' AS rank FROM orgdepartment a WHERE a.DEPARTMENTNO IN ('@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),4)','@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),3)', '@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),2)','@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM)') UNION ALL SELECT a.EXT4 as approver, a.EXT2, '2' AS rank FROM orgdepartment a WHERE a.DEPARTMENTNO IN ('@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),4)','@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),3)', '@getDeptCode(@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM),2)','@form(BO_EU_CONTRACT_PURCHASE,DEPTNUM)')) f ORDER BY f.EXT2 DESC , f.rank DESC) Q, (SELECT @f:=0) X) z WHERE z.approver =(select g.CREATEUSER from wfc_process g where g.id ='@processId()')), )
